/**
 * Cloudflare Worker entry:
 *  - serves static build files (/_next/static, /catalog, /icon.svg) from Workers KV (uploaded by scripts/cf-upload-assets.mjs),
 *  - serves cached HTML of storefront pages to anonymous visitors (page cache, below),
 *  - forwards everything else to the OpenNext-generated Next.js handler.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import nextWorker from "./.open-next/worker.js";

type KV = {
  get(key: string, opts: { type: "text"; cacheTtl?: number }): Promise<string | null>;
  getWithMetadata(key: string, type: "arrayBuffer"): Promise<{ value: ArrayBuffer | null; metadata: { ct?: string } | null }>;
  put(key: string, value: string, opts?: { expirationTtl?: number }): Promise<void>;
};
type Env = { STATIC_ASSETS?: KV; CF_VERSION_METADATA?: { id?: string }; [k: string]: unknown };
type Ctx = { waitUntil(p: Promise<unknown>): void };

const STATIC = /^\/(_next\/static\/|catalog\/|icon\.svg$)/;

async function serveAsset(env: Env, pathname: string): Promise<Response | null> {
  if (!env.STATIC_ASSETS) return null;
  const { value, metadata } = await env.STATIC_ASSETS.getWithMetadata(decodeURIComponent(pathname), "arrayBuffer");
  if (!value) return null;
  return new Response(value, {
    headers: {
      "Content-Type": metadata?.ct || "application/octet-stream",
      "Cache-Control": pathname.startsWith("/_next/static/") ? "public, max-age=31536000, immutable" : "public, max-age=86400",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

function withAssets(env: Env): Env {
  return {
    ...env,
    ASSETS: {
      fetch: async (input: Request | string) => {
        const url = new URL(typeof input === "string" ? input : input.url);
        return (await serveAsset(env, url.pathname)) ?? new Response("Not found", { status: 404 });
      },
    },
  };
}

/* ───────────────────────────── Page cache ─────────────────────────────
 * Rendering a page costs CPU time on every visit, and the Workers free plan allows little of it per request.
 * Storefront pages are the same for every anonymous visitor (cart and wishlist live in the browser), so their HTML
 * is kept in KV and served without running Next.js.
 *  - Only GET requests without a query string, without an admin session cookie and without Next.js client-navigation
 *    headers are served from or stored in the cache.
 *  - Keys include the deployment id (a new deploy never serves old HTML), the display currency, and a content version
 *    bumped by every admin save (POST under /admin), so edits appear within about a minute.
 *  - Entries expire after PAGE_TTL, so stock levels and promotions refresh on their own.
 *  - The checkout always re-checks prices and stock on the server, so a cached page can never sell at a stale price.
 */
const PAGE_TTL = 10 * 60;
const VERSION_KEY = "pagecache:content-version";
const CACHEABLE = /^\/(fr|ar|en)(\/(shop|collections|gifts|craftsmanship|track|cart|wishlist|checkout)|\/(collections|category|product|pages)\/[a-z0-9-]+)?\/?$/;
const SECURITY_HEADERS: Record<string, string> = {
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "SAMEORIGIN",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=63072000; includeSubDomains",
};

function cookie(req: Request, name: string) {
  const m = new RegExp(`(?:^|;\\s*)${name}=([^;]*)`).exec(req.headers.get("cookie") || "");
  return m ? decodeURIComponent(m[1]) : null;
}

function cacheable(req: Request, url: URL) {
  if (req.method !== "GET" || url.search) return false;
  if (!CACHEABLE.test(url.pathname)) return false;
  if (cookie(req, "dz_session")) return false;
  const h = req.headers;
  return !(h.get("rsc") || h.get("next-router-state-tree") || h.get("next-router-prefetch") || h.get("next-action"));
}

async function pageKey(env: Env, req: Request, url: URL) {
  const version = (await env.STATIC_ASSETS!.get(VERSION_KEY, { type: "text", cacheTtl: 60 })) || "0";
  const currency = (cookie(req, "dz_currency") || "MAD").replace(/[^A-Z]/g, "").slice(0, 3) || "MAD";
  const deploy = env.CF_VERSION_METADATA?.id || "dev";
  return `page:${deploy}:${version}:${currency}:${url.pathname.replace(/\/$/, "")}`;
}

export default {
  async fetch(request: Request, env: Env, ctx: Ctx) {
    const url = new URL(request.url);
    if ((request.method === "GET" || request.method === "HEAD") && STATIC.test(url.pathname)) {
      const asset = await serveAsset(env, url.pathname);
      if (asset) return asset;
    }

    if (env.STATIC_ASSETS && cacheable(request, url)) {
      const key = await pageKey(env, request, url).catch(() => null);
      const hit = key ? await env.STATIC_ASSETS.get(key, { type: "text" }).catch(() => null) : null;
      if (hit) {
        const headers = new Headers({ ...SECURITY_HEADERS, "Content-Type": "text/html; charset=utf-8", "Cache-Control": "private, no-cache", "X-Page-Cache": "hit" });
        const locale = url.pathname.split("/")[1];
        if (cookie(request, "NEXT_LOCALE") !== locale) headers.append("Set-Cookie", `NEXT_LOCALE=${locale}; Path=/; Max-Age=31536000; SameSite=Lax`);
        return new Response(hit, { headers });
      }
      const res: Response = await nextWorker.fetch(request, withAssets(env), ctx);
      if (key && res.status === 200 && (res.headers.get("content-type") || "").includes("text/html")) {
        const copy = res.clone();
        ctx.waitUntil(copy.text().then((html) => env.STATIC_ASSETS!.put(key, html, { expirationTtl: PAGE_TTL })).catch(() => {}));
      }
      return res;
    }

    const res: Response = await nextWorker.fetch(request, withAssets(env), ctx);
    // Any admin save invalidates cached pages.
    if (env.STATIC_ASSETS && request.method === "POST" && url.pathname.startsWith("/admin") && res.status < 400) {
      ctx.waitUntil(env.STATIC_ASSETS.put(VERSION_KEY, String(Date.now())).catch(() => {}));
    }
    return res;
  },
};
